#include <Wire.h>
#include <EEPROM.h>
#include <LiquidCrystal_I2C.h>
#include <RDA5807M.h>
#include <RDSParser.h>

#define PIN_CLK 2   // энкодер CLK (аппаратное прерывание)
#define PIN_DT  3   // энкодер DT
#define PIN_SW  4   // кнопка энкодера

#define TZ_OFFSET 7          // часовой пояс, Усть-Абакан = UTC+7

const uint16_t FREQ_MIN = 8750;   // единицы: 100 кГц (8750 = 87.5 МГц)
const uint16_t FREQ_MAX = 10800;  // 108.0 МГц

#define PRESET_COUNT    10
#define EEPROM_MAGIC    0
#define EEPROM_FREQH    1
#define EEPROM_FREQL    2
#define EEPROM_VOL      3
#define EEPROM_PRESETS  10   // 10 станций × 2 байта: адреса 10..29

LiquidCrystal_I2C lcd(0x27, 20, 4);   // если сканер показал 0x3F — поправьте
RDA5807M    radio;
RDSParser   rds;

uint16_t freq   = 10000;   // стартовая 100.0 МГц
uint8_t  volume = 8;       // 0..15

enum Mode : uint8_t { MODE_TUNE, MODE_VOLUME, MODE_PRESET };
Mode mode = MODE_TUNE;

uint16_t presets[PRESET_COUNT];
uint8_t  presetIdx = 0;

volatile int8_t encTicks = 0;

char    rdsName[11] = "";
bool    timeValid = false;
uint8_t hour = 0, minute = 0;         // местное время
unsigned long lastTick = 0;

char          msg[21] = "";
unsigned long msgUntil = 0;
bool          savePending = false, needRedraw = true;
unsigned long saveTimer = 0, redrawTimer = 0;

// ---------- RDS ----------
void RDS_process(uint16_t b1, uint16_t b2, uint16_t b3, uint16_t b4) {
  rds.processData(b1, b2, b3, b4);
}

void onRdsName(const char *name) {
  strncpy(rdsName, name, 10);
  rdsName[10] = 0;
  needRedraw = true;
}

void onRdsTime(uint8_t h, uint8_t m) {   // RDS передаёт время в UTC
  int t = (h * 60 + m + TZ_OFFSET * 60 + 1440) % 1440;
  hour = t / 60; minute = t % 60;
  timeValid = true;
  lastTick = millis();
  needRedraw = true;
}

void resetRdsName() {   // сброс имени при смене частоты
  rds.init();
  rdsName[0] = 0;
  needRedraw = true;
}

// ---------- сообщения на экране ----------
void showMsg(const char *text) {
  snprintf(msg, sizeof(msg), "%-20s", text);
  msgUntil = millis() + 1500;
  needRedraw = true;
}

// ---------- энкодер ----------
void encoderISR() {
  static unsigned long lastMs = 0;
  unsigned long now = millis();
  if (now - lastMs < 4) return;   // антидребезг
  lastMs = now;
  encTicks += digitalRead(PIN_DT) ? 1 : -1;
}

// ---------- кнопка ----------
// короткое нажатие: TUNE -> VOLUME -> PRESET -> TUNE
// длинное нажатие:  в TUNE — записать станцию в слот P,
//                   в VOLUME — автопоиск станции,
//                   в PRESET — стереть текущий слот
void handleButton() {
  static bool pressed = false;
  static unsigned long pressTime = 0;
  bool down = (digitalRead(PIN_SW) == LOW);
  if (down && !pressed) { pressed = true; pressTime = millis(); }
  if (!down && pressed) {
    pressed = false;
    bool longP = (millis() - pressTime > 700);

    if (mode == MODE_TUNE) {
      if (longP) savePreset();
      else { mode = MODE_VOLUME; needRedraw = true; }
    } else if (mode == MODE_VOLUME) {
      if (longP) seek(+1);
      else { mode = MODE_PRESET; needRedraw = true; }
    } else {
      if (longP) {          // очистить текущий слот
        presets[presetIdx] = 0;
        EEPROM.update(EEPROM_PRESETS + presetIdx * 2,     0);
        EEPROM.update(EEPROM_PRESETS + presetIdx * 2 + 1, 0);
        showMsg("Cleared");
      }
      mode = MODE_TUNE; needRedraw = true;
    }
  }
}

// ---------- пресеты ----------
void savePreset() {
  presets[presetIdx] = freq;
  EEPROM.update(EEPROM_PRESETS + presetIdx * 2,     highByte(freq));
  EEPROM.update(EEPROM_PRESETS + presetIdx * 2 + 1, lowByte(freq));
  char buf[16];
  snprintf(buf, sizeof(buf), "P%u saved", presetIdx);
  showMsg(buf);
}

void loadPresets() {
  for (uint8_t i = 0; i < PRESET_COUNT; i++) {
    uint16_t f = ((uint16_t)EEPROM.read(EEPROM_PRESETS + i * 2) << 8) |
                  EEPROM.read(EEPROM_PRESETS + i * 2 + 1);
    presets[i] = (f >= FREQ_MIN && f <= FREQ_MAX) ? f : 0;  // защита от мусора
  }
}

// ---------- автопоиск ----------
void seek(int8_t dir) {
  showMsg("Searching...");
  if (dir > 0) radio.seekUp(true); else radio.seekDown(true);
  unsigned long t = millis();
  RADIO_INFO info;
  do { radio.getRadioInfo(&info); } while (!info.tuned && millis() - t < 2000);
  freq = radio.getFrequency();
  resetRdsName();
  savePending = needRedraw = true;
  saveTimer = millis();
}

// ---------- сохранение настроек ----------
void saveSettings() {
  EEPROM.update(EEPROM_MAGIC, 0xAB);
  EEPROM.update(EEPROM_FREQH, highByte(freq));
  EEPROM.update(EEPROM_FREQL, lowByte(freq));
  EEPROM.update(EEPROM_VOL,   volume);
}

// ---------- экран ----------
void drawScreen() {
  char buf[21];
  RADIO_INFO info;
  radio.getRadioInfo(&info);

  snprintf(buf, sizeof(buf), "FM %3d.%1d MHz     %s",
           freq / 100, (freq % 100) / 10, info.stereo ? "ST" : "MO");
  lcd.setCursor(0, 0); lcd.print(buf);

  if (millis() < msgUntil) {                      // временное сообщение
    lcd.setCursor(0, 1); lcd.print(msg);
  } else {                                        // имя станции
    snprintf(buf, sizeof(buf), "%-20s", rdsName);
    lcd.setCursor(0, 1); lcd.print(buf);
  }

  if (mode == MODE_PRESET) {
    snprintf(buf, sizeof(buf), "Preset P%u  %s",
             presetIdx, presets[presetIdx] ? "      " : "empty ");
  } else {
    snprintf(buf, sizeof(buf), "Mode: %-5s P%u Vol: %2d",
             mode == MODE_TUNE ? "TUNE" : "VOL", presetIdx, volume);
  }
  lcd.setCursor(0, 2); lcd.print(buf);

  lcd.setCursor(0, 3);
  uint8_t n = (mode == MODE_VOLUME)
              ? map(volume, 0, 15, 0, 13)      // индикатор громкости
              : map(info.rssi, 0, 63, 0, 13);  // индикатор сигнала
  for (uint8_t i = 0; i < 13; i++) lcd.print(i < n ? '#' : ' ');

  if (timeValid) snprintf(buf, sizeof(buf), " %02d:%02d", hour, minute);
  else           strcpy(buf, "  --:--");
  lcd.print(buf);
}

void setup() {
  Serial.begin(115200);          // первой строкой — для отладки
  Serial.println();
  Serial.println(F("start"));

  // 1. энкодер
  pinMode(PIN_CLK, INPUT_PULLUP);
  pinMode(PIN_DT,  INPUT_PULLUP);
  pinMode(PIN_SW,  INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(PIN_CLK), encoderISR, FALLING);
  Serial.println(F("encoder ok"));

  // 2. дисплей
  Wire.begin();
  Wire.setClock(100000);         // принудительно 100 кГц
  lcd.init();                    // не компилируется — замените на lcd.begin()
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print(F("FM radio starting"));
  Serial.println(F("lcd ok"));

  // 3. EEPROM
  if (EEPROM.read(EEPROM_MAGIC) == 0xAB) {
    freq   = ((uint16_t)EEPROM.read(EEPROM_FREQH) << 8) | EEPROM.read(EEPROM_FREQL);
    volume = EEPROM.read(EEPROM_VOL);
  }
  freq   = constrain(freq, FREQ_MIN, FREQ_MAX);
  volume = constrain(volume, 0, 15);
  loadPresets();
  Serial.println(F("eeprom ok"));

  // 4. тюнер
  radio.init();
  Serial.println(F("radio ok"));
  radio.setMono(false);
  radio.setMute(false);
  radio.setVolume(volume);
  radio.setBandFrequency(RADIO_BAND_FM, freq);
  Serial.println(F("freq ok"));

  // 5. RDS
  radio.attachReceiveRDS(RDS_process);
  rds.attachServiceNameCallback(onRdsName);
  rds.attachTimeCallback(onRdsTime);
  rds.init();
  Serial.println(F("rds ok — setup done"));

  delay(1000);   // дать прочитать стартовую надпись
  needRedraw = true;
}

void loop() {
  // повороты энкодера
  int8_t ticks;
  noInterrupts(); ticks = encTicks; encTicks = 0; interrupts();

  if (ticks != 0) {
    switch (mode) {
      case MODE_TUNE: {                          // настройка частоты
        int16_t f = (int16_t)freq + ticks;
        freq = constrain(f, FREQ_MIN, FREQ_MAX);
        radio.setFrequency(freq);
        resetRdsName();
        break;
      }
      case MODE_VOLUME: {                        // громкость
        int16_t v = (int16_t)volume + ticks;
        volume = constrain(v, 0, 15);
        radio.setVolume(volume);
        break;
      }
      case MODE_PRESET: {                        // выбор слота
        presetIdx = (presetIdx + PRESET_COUNT + ticks) % PRESET_COUNT;
        if (presets[presetIdx]) {                // слот занят — перестраиваемся
          freq = presets[presetIdx];
          radio.setFrequency(freq);
          resetRdsName();
        }
        break;
      }
    }
    savePending = needRedraw = true;
    saveTimer = millis();
  }

  handleButton();
  radio.checkRDS();

  // программный ход минут между RDS-синхронизациями
  if (timeValid && millis() - lastTick >= 60000) {
    lastTick += 60000;
    minute++;
    if (minute >= 60) { minute = 0; hour = (hour + 1) % 24; }
    needRedraw = true;
  }

  if (savePending && millis() - saveTimer > 2000) {  // EEPROM не чаще 1 раза в 2 с
    savePending = false;
    saveSettings();
  }

  if (needRedraw && millis() - redrawTimer > 200) {
    redrawTimer = millis();
    needRedraw = false;
    drawScreen();
  }
}
